// 🇺🇸 USDATA — us.js + us_pics_1.js + us_pics_2.js, the United States Path's cards and pictures (PLAN_us_unit_2026-11-16.md §3,
//   §6, §9 slice 1; her approval 2026-11-17: "great on the us", "buil the us"). The three files are GENERATED by
//   tools/build_us_js.py (photos from Wikimedia Commons — Public domain / CC0 / CC BY only — and drawings + maps made in
//   tools/us_runtime.js over geo.js). Nothing in the app loads them yet (slice 2 USPATH adds HA_LAZY_FILES and the unit). Pins:
//   · 10 stages, 11 decks, 370 cards, each stage's and deck's count as the plan says; order 1…370 stage by stage;
//   · every card name is a legal database key (index.html's own mastDefKeyOk) and no name is used twice in the unit;
//   · the 20 built-in U.S. History cards: names and backs byte for byte the app's built-in catalog and MAST_VOCAB_DEFS
//     (so a kid's live cards adopt with zero writes); the 47 presidents' names and years are notebooks.js's list exactly;
//   · flash decks carry no back, flip decks always do; the answers that follow an officeholder are flagged;
//   · every card but the Civics Test has a picture: photos resolve to small JPEGs in the right file (Stages 1–4 in
//     us_pics_1.js), drawings and maps are whole SVGs; each picture has a credit, every photo licence is PD / CC0 / CC BY;
//   · the 2025 USCIS list: 124 cards (128 minus the four "your state" questions), the starred ones first, every "taught by"
//     card exists, and the questions no earlier card teaches are pinned (so a change is seen);
//   · size caps, and no family or kid name anywhere (historical names like Abraham Lincoln and Ellis Island aside).
//   run: node test_us_data.js
const fs = require("fs"), path = require("path"), vm = require("vm");
let pass = 0, fail = 0;
const ok = (n, c, x) => { if (c) { pass++; console.log("  ok  - " + n); } else { fail++; console.log("  FAIL- " + n + (x !== undefined ? "  " + JSON.stringify(x).slice(0, 400) : "")); } };
const rd = f => fs.readFileSync(path.join(__dirname, f), "utf8");
const usSrc = rd("us.js"), p1Src = rd("us_pics_1.js"), p2Src = rd("us_pics_2.js"), geoSrc = rd("geo.js"), html = rd("index.html"), nb = rd("notebooks.js");

// ── load the browser's way: geo.js, the pictures, then us.js — all classic scripts on one window ──
const win = {}; const ctx = { window: win, module: undefined, console }; vm.createContext(ctx);
vm.runInContext(p1Src, ctx); vm.runInContext(p2Src, ctx); vm.runInContext(usSrc, ctx);
const U = win.HoweUS;
ok("us.js loads as a classic script → window.HoweUS; the photo files fill window.HoweUSPics", !!(U && U.svg && U.text && U.card && win.HoweUSPics));
const Unode = require(path.join(__dirname, "us.js"));
ok("us.js also loads as a Node module", !!(Unode && Unode.cards && Unode.cards.length === U.cards.length));
const cards = U.cards;

// ── stages, decks, counts ──
const STAGE_N = { 1: 11, 2: 16, 3: 24, 4: 30, 5: 37, 6: 30, 7: 47, 8: 25, 9: 26, 10: 124 };
const DECK_N = { "American Symbols": 11, "American Holidays": 11, "Famous Presidents": 5, "Famous Americans": 30, "Civics": 33, "13 Colonies": 13,
  "U.S. History": 48, "American Battles": 25, "Amendments": 23, "Presidents": 47, "Civics Test": 124 };
const byStage = {}, byDeck = {}; cards.forEach(c => { byStage[c.stage] = (byStage[c.stage] || 0) + 1; byDeck[c.deck] = (byDeck[c.deck] || 0) + 1; });
ok("370 cards", cards.length === 370, cards.length);
ok("10 stages, numbered 1–10, each with its plan count", U.stages.length === 10 && U.stages.every((s, i) => s.n === i + 1) && JSON.stringify(byStage) === JSON.stringify(STAGE_N), byStage);
ok("11 decks in the plan's order, each with its count", JSON.stringify(U.decks.map(d => d.key)) === JSON.stringify(Object.keys(DECK_N)) && JSON.stringify(byDeck) === JSON.stringify(Object.fromEntries(Object.keys(DECK_N).map(k => [k, byDeck[k]]))) && Object.keys(DECK_N).every(k => byDeck[k] === DECK_N[k]), byDeck);
ok("readyAt never above a stage's card count, and set where the plan sets it", U.stages.every(s => s.readyAt == null || s.readyAt <= STAGE_N[s.n]) && U.stages.filter(s => s.readyAt).length === 9);
ok("order runs 1…370, stage by stage", cards.every((c, i) => c.order === i + 1) && cards.every((c, i) => !i || cards[i - 1].stage <= c.stage));
const MODES = { "American Symbols": "flash", "American Holidays": "flash", "Famous Presidents": "flash", "13 Colonies": "flash" };
ok("deck modes: flash for the say-what-you-see decks, flip for the rest; intro 2 at a time for Stages 1–3 decks", U.decks.every(d => d.mode === (MODES[d.key] || "flip")) && U.decks.filter(d => d.introCap === 2).map(d => d.key).join() === "American Symbols,American Holidays,Famous Presidents,Famous Americans");
ok("flash cards carry no back; every flip card has one", cards.every(c => MODES[c.deck] ? c.def == null : (typeof c.def === "string" && c.def.length > 0)), cards.filter(c => MODES[c.deck] ? c.def != null : !c.def).map(c => c.name));
ok("the U.S. History deck spans Stages 5, 6, 8 and 9 (10 · 4 · 16 · 18)", JSON.stringify([5, 6, 8, 9].map(n => cards.filter(c => c.deck === "U.S. History" && c.stage === n).length)) === "[10,4,16,18]");
ok("Famous Americans spans Stage 3 (24) and Stage 5 (6); Civics Stage 4 (30) and Stage 6 (3); battles 8 · 9 · 8", cards.filter(c => c.deck === "Famous Americans" && c.stage === 3).length === 24 && cards.filter(c => c.deck === "Civics" && c.stage === 6).length === 3 && JSON.stringify([5, 8, 9].map(n => cards.filter(c => c.deck === "American Battles" && c.stage === n).length)) === "[8,9,8]");

// ── names ──
const keyOkSrc = (html.match(/function mastDefKeyOk\(p\)\{[^}]*\}/) || [""])[0];
const mastDefKeyOk = keyOkSrc ? new Function(keyOkSrc + "; return mastDefKeyOk;")() : null;
ok("index.html's mastDefKeyOk found", !!mastDefKeyOk);
ok("every card name is a legal database key (no . # $ [ ] /)", mastDefKeyOk && cards.every(c => mastDefKeyOk(c.name)), cards.filter(c => mastDefKeyOk && !mastDefKeyOk(c.name)).map(c => c.name));
const seen = {}; cards.forEach(c => { seen[c.name] = (seen[c.name] || 0) + 1; });
ok("no card name is used twice anywhere in the unit (definitions are keyed by the front)", Object.keys(seen).every(k => seen[k] === 1), Object.keys(seen).filter(k => seen[k] > 1));
ok("every card has a family and a stage the stages list knows", cards.every(c => c.family && U.stages.some(s => s.n === c.stage)));

// ── the built-in U.S. History cards: byte for byte the app's ──
function lit(src, start, open, close) { const i = src.indexOf(start); if (i < 0) return null; let j = src.indexOf(open, i), d = 0, q = null;
  for (let k = j; k < src.length; k++) { const c = src[k]; if (q) { if (c === "\\") { k++; continue; } if (c === q) q = null; continue; }
    if (c === '"' || c === "'" || c === "`") { q = c; continue; } if (c === open) d++; else if (c === close) { d--; if (!d) return src.slice(j, k + 1); } } return null; }
const builtNames = JSON.parse(lit(html, '"U.S. History":["Jamestown"', "[", "]"));
const VOCAB = (new Function("return " + lit(html, "const MAST_VOCAB_DEFS={", "{", "}")))();
const bi = cards.filter(c => c.builtin);
ok("20 built-in cards, all in the U.S. History deck, flagged builtin", bi.length === 20 && bi.every(c => c.deck === "U.S. History") && builtNames.length === 20);
ok("the built-in names are the app's built-in catalog's 20, exactly", JSON.stringify(bi.map(c => c.name).sort()) === JSON.stringify(builtNames.slice().sort()), bi.map(c => c.name));
ok("every built-in back is MAST_VOCAB_DEFS's, byte for byte", bi.every(c => c.def === VOCAB[c.name.toLowerCase()]), bi.filter(c => c.def !== VOCAB[c.name.toLowerCase()]).map(c => c.name));
ok("the four amendment cards the built-in deck holds (13th, 14th, 15th, 19th) are U.S. History cards in Stage 6, not Amendments cards",
  ["13th", "14th", "15th", "19th"].every(n => { const c = cards.find(x => x.name === n + " Amendment"); return c && c.deck === "U.S. History" && c.stage === 6 && c.builtin; }) && byDeck["Amendments"] === 23);
ok("no other unit card front is a MAST_VOCAB_DEFS key except the 20 built-ins and the 13 colonies (flash, no back)", cards.filter(c => !c.builtin && VOCAB[c.name.toLowerCase()] != null).every(c => c.deck === "13 Colonies"), cards.filter(c => !c.builtin && VOCAB[c.name.toLowerCase()] != null && c.deck !== "13 Colonies").map(c => c.name));

// ── presidents: notebooks.js's list exactly ──
const LN = JSON.parse(lit(nb, "var LN_EXTRA = ", "{", "}"));
const NBP = LN.enrich.presidents;
const pres = cards.filter(c => c.deck === "Presidents");
ok("47 president cards, 1st President … 47th President, in order", pres.length === 47 && pres.every((c, i) => c.name === NBP[i][0] + " President"));
ok("each back starts with notebooks.js's name · years, then its one line", pres.every((c, i) => c.def === NBP[i][1] + " · " + NBP[i][2] + " · " + NBP[i][3]), pres.filter((c, i) => c.def !== NBP[i][1] + " · " + NBP[i][2] + " · " + NBP[i][3]).map(c => c.name));
ok("every president has the 6th–8th line (more)", pres.every(c => typeof c.more === "string" && c.more.length > 10));
ok("eight eras as families, Founders first, Today last", [...new Set(pres.map(c => c.family))].join("|") === "Founders|A growing nation|Toward war|Rebuilding and the Gilded Age|A new century|Depression, war and the Cold War|Into a new century|Today");
ok("Cleveland (22nd, 24th) and Trump (45th, 47th) share one portrait each", pres[21].pic === pres[23].pic && pres[44].pic === pres[46].pic && U.svg("Presidents", "22nd President") === U.svg("Presidents", "24th President"));
ok("the Stage-2 president every kid knows shares the Stage-7 portrait", U.svg("Famous Presidents", "Abraham Lincoln") === U.svg("Presidents", "16th President") && !!U.svg("Presidents", "16th President"));
ok("answers that change are flagged: the president now (Stage 2) and the Civics Test's President, VP, Speaker, Chief Justice", JSON.stringify(cards.filter(c => c.changes).map(c => c.deck).sort()) === JSON.stringify(["Civics Test", "Civics Test", "Civics Test", "Civics Test", "Famous Presidents"]));

// ── pictures ──
const nonCT = cards.filter(c => c.deck !== "Civics Test");
ok("every card but the Civics Test has a picture spec; Civics Test cards have none", nonCT.every(c => !!c.pic) && cards.filter(c => c.deck === "Civics Test").every(c => !c.pic));
const PICS = win.HoweUSPics;
const photos = [...new Set(nonCT.filter(c => c.pic.indexOf("photo:") === 0).map(c => c.pic.slice(6)))];
ok("104 distinct photos, every one in a photo file", photos.length === 104 && photos.every(id => typeof PICS[id] === "string" && PICS[id].indexOf("data:image/jpeg;base64,") === 0), photos.filter(id => !PICS[id]));
const P1 = require(path.join(__dirname, "us_pics_1.js")), P2 = require(path.join(__dirname, "us_pics_2.js"));
const early = new Set(nonCT.filter(c => c.stage <= 4 && c.pic.indexOf("photo:") === 0).map(c => c.pic.slice(6)));
ok("every photo a Stage 1–4 card uses is in us_pics_1.js; the rest are in us_pics_2.js; none in both", [...early].every(id => P1[id]) && photos.filter(id => !early.has(id)).every(id => P2[id] && !P1[id]) && Object.keys(P1).every(id => !P2[id]));
const bytesOf = d => Buffer.from(d.split(",")[1], "base64");
const sizes = photos.map(id => [id, bytesOf(PICS[id]).length]);
ok("every photo is a real JPEG of at most 14 KB", sizes.every(([id, n]) => n <= 14 * 1024 && n > 1500) && photos.every(id => { const b = bytesOf(PICS[id]); return b[0] === 0xFF && b[1] === 0xD8; }), sizes.filter(s => s[1] > 14 * 1024));
const LIC = /^(Public domain|PD\b|CC0|CC BY \d(\.\d)?$)/;
const photoCredits = Object.keys(U.credits).filter(k => k.indexOf("photo:") === 0);
ok("one credit per photo, each PD / CC0 / CC BY (never BY-SA), with its Commons file page and a credit line naming the licence",
  photoCredits.length === 104 && photoCredits.every(k => { const c = U.credits[k]; return LIC.test(c.licence) && !/SA/.test(c.licence) && /^https:\/\/commons\.wikimedia\.org\/wiki\/File:/.test(c.page) && c.line.indexOf(c.licence) >= 0 && c.line.indexOf("Wikimedia Commons") >= 0; }),
  photoCredits.filter(k => !LIC.test(U.credits[k].licence)));
ok("every CC BY photo credits an author", photoCredits.filter(k => /^CC BY/.test(U.credits[k].licence)).every(k => U.credits[k].artist && U.credits[k].artist.length > 2));
ok("every card with a picture has a credit line", nonCT.every(c => U.credit(c.deck, c.name).length > 5), nonCT.filter(c => !U.credit(c.deck, c.name)).map(c => c.name));
const wellFormed = t => typeof t === "string" && /^<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg" viewBox="[-\d. ]+"/.test(t) && /<\/svg>$/.test(t) && !/NaN|undefined|null|Infinity/.test(t) &&
  (t.match(/<g\b/g) || []).length === (t.match(/<\/g>/g) || []).length;
const drawn = nonCT.filter(c => !/^(photo|colony|pin):/.test(c.pic));
ok("every drawn picture (flag, holidays, civics, amendments, badges) is a whole SVG", drawn.every(c => wellFormed(U.text(c.pic))), drawn.filter(c => !wellFormed(U.text(c.pic))).map(c => c.pic));
ok("…and comes back as an SVG data URI, under 20 KB (the 435-seat House drawn as dotted paths)", drawn.every(c => { const u = U.svg(c.deck, c.name); return /^data:image\/svg\+xml;utf8,/.test(u) && u.length < 20000; }));
ok("the flag has 13 stripes' worth of red (7) and 50 stars", (() => { const t = U.text("flag"); return (t.match(/fill="#B22234"/g) || []).length === 7 && (t.match(/<polygon/g) || []).length === 50; })());
ok("people with no true likeness (Squanto, Sacagawea, Betsy Ross) get a drawn badge, not a face", ["Squanto", "Sacagawea", "Betsy Ross"].every(n => U.card("Famous Americans", n).pic === "badge:" + n));
const mapped = nonCT.filter(c => /^(colony|pin):/.test(c.pic));
ok("without geo.js the 13-colony and pin pictures wait (null), never break", mapped.every(c => U.svg(c.deck, c.name) === null));
const gwin = {}; vm.runInNewContext(geoSrc, { window: gwin, module: undefined, console }); U.geo = gwin.HoweGeo;
ok("geo.js loaded → every 13-colony map and every battle / war pin is a whole SVG", mapped.length === 13 + 25 + 15 && mapped.every(c => wellFormed(U.text(c.pic))), mapped.filter(c => !wellFormed(U.text(c.pic))).map(c => c.pic));
ok("a colony map lights its colony in its region colour", /fill="#E69F00"/.test(U.text("colony:North Carolina")) && /fill="#0072B2"/.test(U.text("colony:Massachusetts")));
ok("US battles are pinned on the US map, overseas ones on the world map; Pearl Harbor on the Hawaii inset",
  U.data.pins["Gettysburg"][0] === "us" && U.data.pins["D-Day"][0] === "world" && U.data.pins["Pearl Harbor"][0] === "hi" && U.data.pins["Pearl Harbor"][2] > 450 && U.data.pins["Midway"][0] === "world");
ok("the North Carolina battles sit inside North Carolina's outline box on the US map", ["Moores Creek Bridge", "Guilford Courthouse", "Bentonville"].every(n => { const b = gwin.HoweGeo.data.us.state["North Carolina"].match(/-?\d+(\.\d+)?/g).map(Number);
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9; for (let i = 0; i + 1 < b.length; i += 2) { x0 = Math.min(x0, b[i]); x1 = Math.max(x1, b[i]); y0 = Math.min(y0, b[i + 1]); y1 = Math.max(y1, b[i + 1]); }
  const p = U.data.pins[n]; return p[1] >= x0 && p[1] <= x1 && p[2] >= y0 && p[2] <= y1; }));
U.geo = null;
ok("every holiday, icon, amendment and badge a card names exists in the runtime", nonCT.every(c => { const [k, a] = c.pic.split(":"); return k === "holiday" ? U.holidays.includes(a) : k === "icon" ? U.icons.includes(a) : k === "amend" ? U.amendIcons.includes(+a) : k === "badge" ? U.badges.includes(a) : true; }));
ok("all 27 amendments draw an icon", U.amendIcons.length === 27);

// ── the 2025 USCIS civics test ──
const CTc = cards.filter(c => c.deck === "Civics Test");
const STAR = [2, 7, 12, 20, 30, 36, 38, 39, 44, 52, 61, 66, 74, 78, 86, 94, 113, 115, 121, 126];
const teach = U.uscis.teach;
ok("124 question cards = the 2025 list's 128 minus the four 'your state' ones (23, 29, 61, 62)", CTc.length === 124 && JSON.stringify(Object.keys(U.uscis.local).map(Number)) === "[23,29,61,62]" && CTc.every(c => teach[c.name]) && new Set(CTc.map(c => teach[c.name].q)).size === 124 && CTc.every(c => ![23, 29, 61, 62].includes(teach[c.name].q)));
ok("USCIS's starred list pinned; the 19 starred cards (61 is a 'your state' one) come first as their own family", JSON.stringify(U.uscis.star) === JSON.stringify(STAR) && CTc.slice(0, 19).every(c => c.family === "The big twenty" && STAR.includes(teach[c.name].q)) && CTc.filter(c => c.family === "The big twenty").length === 19);
ok("then the USCIS sections in order", [...new Set(CTc.map(c => c.family))].join("|") === "The big twenty|Principles of American Government|System of Government|Rights and Responsibilities|Colonial Period and Independence|The 1800s|Recent American History|Symbols and Holidays");
const refOk = r => r.indexOf("geo:") === 0 || (() => { const [d, n] = r.split("|"); return !!U.card(d, n); })();
ok("every 'taught by' card exists in the unit (or the Geography Path)", CTc.every(c => teach[c.name].cards.every(refOk)), CTc.filter(c => !teach[c.name].cards.every(refOk)).map(c => c.name));
ok("every 'taught by' card sits in an earlier stage than the test", CTc.every(c => teach[c.name].cards.filter(r => r.indexOf("geo:") < 0).every(r => { const [d, n] = r.split("|"); return U.card(d, n).stage < 10; })));
const UNTAUGHT = [12, 30, 39, 45, 47, 48, 49, 54, 55, 56, 57, 67, 72, 124];
ok("the questions no earlier card teaches are known and pinned (economic system, Speaker, VP, judges, Cabinet, Electoral College, Court, Oath, Selective Service, the motto)", JSON.stringify(U.uscis.untaught) === JSON.stringify(UNTAUGHT), U.uscis.untaught);

// ── size and names ──
ok("us.js under 250 KB, us_pics_1.js under 700 KB, us_pics_2.js under 1.2 MB", usSrc.length < 250 * 1024 && p1Src.length < 700 * 1024 && p2Src.length < 1200 * 1024, [usSrc.length, p1Src.length, p2Src.length]);
const HIST = /abraham lincoln|lincoln memorial|lincoln's|lincolnatgettysburg|lincoln o-77|ellis island|andrew jackson|andrew johnson|zachary taylor|david hume kennerly|david valdez|david bachrach|camp david|howe academy|andrew j\. russell|ellis_island/gi;
const NAMES = /\b(adrienne|andrew|julian|lincoln|ellis|lucy|sara|caleb|taylor|kenzie|dewalt|burris|melanie|david)\b/i;
const strip = s => s.replace(/data:image\/jpeg;base64,[A-Za-z0-9+\/=]+/g, "").replace(HIST, "");
["us.js", "us_pics_1.js", "us_pics_2.js", "tools/build_us_js.py", "tools/us_runtime.js", "tools/us_pics.json"].forEach(f => {
  const s = strip(rd(f)); ok("no family or kid name in " + f + " (historical names aside)", !NAMES.test(s), (s.match(NAMES) || [])[0]); });

console.log("\n" + pass + " passed, " + fail + " failed");
process.exit(fail ? 1 : 0);
